<script setup lang="ts">
import {onMounted,onBeforeUnmount,watch,ref} from 'vue';
import Konva from 'konva';
import {useEditor} from '../stores/editor';
import {area,bounds} from '../domain/geometry';
const editor=useEditor(),host=ref<HTMLDivElement>();let stage:Konva.Stage,layer:Konva.Layer,observer:ResizeObserver;let scale=65,pan={x:90,y:75};let space=false;const grid=ref(true);
function draw(){if(!stage)return;layer.destroyChildren();layer.scale({x:scale,y:scale});layer.position(pan);const width=stage.width(),height=stage.height();
 if(grid.value){const step=scale<35?1:.5;for(let x=Math.floor(-pan.x/scale/step)*step;x<(width-pan.x)/scale;x+=step)layer.add(new Konva.Line({points:[x,-pan.y/scale,x,(height-pan.y)/scale],stroke:'#dce3e0',strokeWidth:1/scale,listening:false}));for(let z=Math.floor(-pan.y/scale/step)*step;z<(height-pan.y)/scale;z+=step)layer.add(new Konva.Line({points:[-pan.x/scale,z,(width-pan.x)/scale,z],stroke:'#dce3e0',strokeWidth:1/scale,listening:false}));}
 for(const room of editor.document.rooms){const b=bounds(room.points),selected=editor.selected?.id===room.id;const group=new Konva.Group({draggable:!editor.document.architectureLocked});const shape=new Konva.Line({points:room.points.flatMap(p=>[p.x,p.z]),closed:true,fill:selected?'#d3e4db':room.color,stroke:selected?'#33694e':'#b4c7bc',strokeWidth:2/scale});group.add(shape);
  group.add(new Konva.Text({x:b.minX,y:(b.minZ+b.maxZ)/2-.22,width:b.maxX-b.minX,text:room.name+'\n'+area(room.points).toFixed(2)+' м²',fontSize:13/scale,lineHeight:1.5,align:'center',fill:'#254037',listening:false}));
  group.add(new Konva.Text({x:b.minX,y:b.minZ+.15,width:b.maxX-b.minX,text:(b.maxX-b.minX).toFixed(2)+' × '+(b.maxZ-b.minZ).toFixed(2)+' м',fontSize:11/scale,align:'center',fill:'#71877c',listening:false}));
  group.on('click tap',e=>{e.cancelBubble=true;editor.selected={kind:'room',id:room.id};});
  group.on('dragstart',()=>{if(space){group.stopDrag();return;}editor.selected={kind:'room',id:room.id};});
  group.on('dragend',()=>{const dx=Math.round(group.x()*20)/20,dz=Math.round(group.y()*20)/20;if(editor.walls.some(w=>w.roomIds.length===2&&w.roomIds.includes(room.id))){editor.error='Комната соединена с соседней. Сдвиньте общую стену или нажмите «Отсоединить».';}else editor.architectural('Переместить комнату',p=>{p.rooms.find(r=>r.id===room.id)!.points.forEach(v=>{v.x+=dx;v.z+=dz;});});draw();});layer.add(group);
 }
 for(const wall of editor.walls){const line=new Konva.Line({points:[wall.a.x,wall.a.z,wall.b.x,wall.b.z],stroke:editor.selected?.id===wall.id?'#c7803d':wall.roomIds.length===2?'#687d73':'#324f43',strokeWidth:wall.thickness,lineCap:'square',hitStrokeWidth:Math.max(wall.thickness,10/scale)});line.on('click tap',e=>{e.cancelBubble=true;editor.selected={kind:'wall',id:wall.id};});layer.add(line);}
 for(const o of editor.document.openings){const w=editor.walls.find(w=>w.id===o.wallId);if(!w)continue;const dx=(w.b.x-w.a.x)/w.length,dz=(w.b.z-w.a.z)/w.length;const a=o.offset-o.width/2,b=o.offset+o.width/2;const line=new Konva.Line({points:[w.a.x+dx*a,w.a.z+dz*a,w.a.x+dx*b,w.a.z+dz*b],stroke:o.kind==='window'?'#8ecfdf':'#f7f8f3',strokeWidth:w.thickness+.04,hitStrokeWidth:.3});line.on('click tap',e=>{e.cancelBubble=true;editor.selected={kind:'opening',id:o.id};});layer.add(line);}
 for(const f of editor.variant.furniture.filter(f=>f.visible)){const group=new Konva.Group({x:f.x,y:f.z,rotation:f.rotation,draggable:true});group.add(new Konva.Rect({x:-f.width/2,y:-f.depth/2,width:f.width,height:f.depth,fill:f.material.color,stroke:editor.selected?.id===f.id?'#b5682a':'#526558',strokeWidth:2/scale,cornerRadius:.02}));group.add(new Konva.Text({x:-f.width/2,y:-.1,width:f.width,text:f.name,fontSize:11/scale,align:'center',fill:'#263a2e',listening:false}));group.on('click tap',e=>{e.cancelBubble=true;editor.selected={kind:'furniture',id:f.id};});group.on('dragend',()=>{editor.edit('Переместить мебель',p=>{const item=p.variants.find(v=>v.id===p.activeVariantId)!.furniture.find(i=>i.id===f.id)!;item.x=Math.round(group.x()*100)/100;item.z=Math.round(group.y()*100)/100;});});layer.add(group);}
 layer.batchDraw();}
function fit(){if(!stage||!editor.document.rooms.length)return;const b=bounds(editor.document.rooms.flatMap(r=>r.points));scale=Math.min(90,(stage.width()-120)/(b.maxX-b.minX+1),(stage.height()-120)/(b.maxZ-b.minZ+1));pan={x:(stage.width()-(b.maxX-b.minX)*scale)/2-b.minX*scale,y:(stage.height()-(b.maxZ-b.minZ)*scale)/2-b.minZ*scale};draw();}
function key(e:KeyboardEvent){if((e.target as HTMLElement).matches('input,textarea,select'))return;if(e.code==='Space'){space=e.type==='keydown';stage?.draggable(space);e.preventDefault();}}
onMounted(()=>{stage=new Konva.Stage({container:host.value!,width:host.value!.clientWidth,height:host.value!.clientHeight});layer=new Konva.Layer();stage.add(layer);stage.on('wheel',e=>{e.evt.preventDefault();const pointer=stage.getPointerPosition()!,old=scale;scale=Math.max(12,Math.min(350,scale*(e.evt.deltaY<0?1.1:1/1.1)));pan={x:pointer.x-(pointer.x-pan.x)*scale/old,y:pointer.y-(pointer.y-pan.y)*scale/old};draw();});stage.on('click tap',e=>{if(e.target===stage)editor.selected=null;});stage.on('dragend',e=>{if(e.target===stage){pan.x+=stage.x();pan.y+=stage.y();stage.position({x:0,y:0});draw();}});observer=new ResizeObserver(()=>{stage.size({width:host.value!.clientWidth,height:host.value!.clientHeight});draw();});observer.observe(host.value!);window.addEventListener('keydown',key);window.addEventListener('keyup',key);draw();});
onBeforeUnmount(()=>{observer?.disconnect();stage?.destroy();window.removeEventListener('keydown',key);window.removeEventListener('keyup',key);});watch(()=>[editor.document,editor.selected],draw,{deep:false});
</script>
<template><div class="canvas-shell"><div ref="host" class="canvas-host"/><div class="viewport-tools"><button @click="fit">Весь план</button><button @click="grid=!grid;draw()">Сетка {{grid?'вкл':'выкл'}}</button></div><div class="viewport-help">Колесо — масштаб · Пробел + движение — сдвиг · Размеры в метрах</div><div v-if="!editor.document.rooms.length" class="empty-plan"><span class="empty-symbol">⌑</span><h2>Ваш дом начинается с комнаты</h2><p>Задайте размеры, соедините комнаты<br>и переходите к интерьеру.</p><button class="primary" @click="editor.addRoom">Создать первую комнату</button></div></div></template>
